// Логотип берётся из файла /logo.svg (папка public на GitHub). Если файла нет
// или он не загрузился — подставляется встроенная копия MERINO_LOGO.
function MerinoLogo() {
  return (
    <img
      src="/logo.svg"
      alt="Merino Home"
      onError={(e) => {
        if (e.currentTarget.dataset.fallback) return;
        e.currentTarget.dataset.fallback = "1";
        e.currentTarget.src = MERINO_LOGO;
      }}
    />
  );
}

