// ---------- helpers ----------

const rub = (n) =>
  new Intl.NumberFormat("ru-RU", { maximumFractionDigits: 0 }).format(Math.round(n)) + " ₽";

const num = (n) => new Intl.NumberFormat("ru-RU").format(n);

// Единицы вида "100 г" / "100 мл" сами начинаются с числа, поэтому просто
// склеивать их с количеством нельзя — "40 100 г" читается как одно число.
// Разделяем знаком "×": "40 × 100 г".
const fmtQty = (quantity, unit) => `${num(quantity)}${/^\d/.test(unit) ? " × " : " "}${unit}`;

// Текущее распределение единиц инвентаря по местам: старт — весь totalQuantity
// на складе, дальше применяем все перемещения (откуда минус, куда плюс).
// Порядок перемещений не важен — это просто сумма подписанных дельт.
const getAssetDistribution = (asset, transfers) => {
  const dist = { warehouse: asset.totalQuantity };
  transfers
    .filter((t) => t.assetId === asset.id)
    .forEach((t) => {
      dist[t.fromKey] = (dist[t.fromKey] || 0) - t.quantity;
      dist[t.toKey] = (dist[t.toKey] || 0) + t.quantity;
    });
  return dist;
};

const todayISO = () => new Date().toISOString().slice(0, 10);

const fmtDate = (iso) => {
  const d = new Date(iso + "T00:00:00");
  return d.toLocaleDateString("ru-RU", { day: "2-digit", month: "2-digit", year: "numeric" });
};

// Полная метка даты-времени (для журнала изменений — в отличие от выдач и
// поступлений, тут за один день может случиться несколько правок подряд).
const nowStamp = () => new Date().toISOString();

const fmtDateTime = (iso) => {
  const d = new Date(iso);
  return d.toLocaleString("ru-RU", { day: "2-digit", month: "2-digit", year: "numeric", hour: "2-digit", minute: "2-digit" });
};

// Раньше номера строились простым счётчиком, который каждый раз стартовал
// заново со значения 100 при каждой перезагрузке страницы/новом деплое.
// Из-за этого позиции, добавленные в РАЗНЫХ сеансах, но одна за другой по
// счёту, могли получить ОДИНАКОВЫЙ номер — и приложение путало их местами
// (например, при клике на "варианты закупки" открывались сразу обе). Теперь
// номер строится из текущего времени и случайной части — так совпадение
// практически исключено, даже между разными сеансами и устройствами.
let idCounter = 0;
const nextId = (prefix) =>
  `${prefix}${Date.now().toString(36)}${(idCounter++).toString(36)}${Math.random().toString(36).slice(2, 6)}`;

