// ---------- экспорт в Excel ----------

const downloadWorkbook = (sheets, filename) => {
  const wb = XLSX.utils.book_new();
  sheets.forEach(({ name, rows }) => {
    const ws = XLSX.utils.json_to_sheet(rows);
    XLSX.utils.book_append_sheet(wb, ws, name.slice(0, 31));
  });
  XLSX.writeFile(wb, filename);
};

// Полная выгрузка всех накопленных данных склада: каталог, журнал выдач,
// журнал поступлений и реестр объектов — каждое на отдельном листе.
const exportAllData = (items, issues, receipts, objects, purchaseOptions = []) => {
  const itemRows = items.map((i) => ({
    "Наименование": i.name,
    "Категория": i.category,
    "Ед. изм.": i.unit,
    "Остаток": i.quantity,
    "Мин. запас": i.minQuantity,
    "Себестоимость ед., ₽": Math.round(i.unitCost * 100) / 100,
    "Стоимость остатка, ₽": Math.round(i.quantity * i.unitCost),
  }));

  const issueRows = issues.map((s) => ({
    "Дата": fmtDate(s.date),
    "Объект (номер)": s.roomNumber,
    "Объект (название)": s.roomName,
    "Материал": items.find((i) => i.id === s.itemId)?.name || "—",
    "Количество": s.qty,
    "Себестоимость, ₽": s.cost,
    "Комментарий": s.note || "",
    "Статус": s.cancelled ? "Отменено" : "Действует",
  }));

  const receiptRows = receipts.map((r) => ({
    "Дата": fmtDate(r.date),
    "Материал": items.find((i) => i.id === r.itemId)?.name || "—",
    "Количество": r.qty,
    "Цена за единицу, ₽": Math.round(r.unitCost * 100) / 100,
    "Сумма закупки, ₽": r.totalCost,
    "Поставщик / комментарий": r.supplier || "",
  }));

  const objectRows = objects.map((o) => ({
    "Номер": o.number,
    "Название": o.name,
    "Статус": o.active ? "Активен" : "Выбыл",
  }));

  const purchaseOptionRows = purchaseOptions.map((o) => ({
    "Материал": items.find((i) => i.id === o.itemId)?.name || "—",
    "Поставщик / магазин": o.source,
    "Цена, ₽": o.price || "",
    "Ссылка": o.url || "",
    "Комментарий": o.note || "",
    "Дата добавления": fmtDate(o.date),
  }));

  downloadWorkbook(
    [
      { name: "Каталог", rows: itemRows },
      { name: "Журнал выдач", rows: issueRows },
      { name: "Журнал поступлений", rows: receiptRows },
      { name: "Объекты", rows: objectRows },
      { name: "Варианты закупки", rows: purchaseOptionRows },
    ],
    `sklad-merino-home-${todayISO()}.xlsx`
  );
};

// Выгрузка отчёта по затратам за выбранный период — сводка + разбивка по
// объектам и категориям, с учётом текущей наценки на логистику, плюс полная
// построчная детализация каждой выдачи.
const exportReport = (periodLabel, summary, byRoom, byCategory, detailedRows) => {
  const summaryRows = [
    { "Показатель": "Период", "Значение": periodLabel },
    { "Показатель": "Себестоимость выдач, ₽", "Значение": Math.round(summary.totalCost) },
    { "Показатель": `Логистика (${summary.markupPercent}%), ₽`, "Значение": Math.round(summary.markupAmount) },
    { "Показатель": "Итого к выставлению, ₽", "Значение": Math.round(summary.billedTotal) },
    { "Показатель": "Единиц выдано", "Значение": summary.totalQty },
    { "Показатель": "Объектов обслужено", "Значение": summary.roomsCount },
  ];

  const roomRows = byRoom.map((a) => ({
    "Номер": a.roomNumber,
    "Название": a.roomName,
    "Себестоимость, ₽": Math.round(a.cost),
    "Логистика, ₽": Math.round(a.logistics),
    "Итого к выставлению, ₽": Math.round(a.billed),
    "Единиц": a.qty,
    "Кол-во выдач": a.issues,
  }));

  const categoryRows = byCategory.map((c) => ({
    "Категория": c.cat,
    "Себестоимость, ₽": Math.round(c.cost),
  }));

  const detailRows = (detailedRows || []).map((d) => ({
    "Дата": fmtDate(d.date),
    "Объект (номер)": d.roomNumber,
    "Объект (название)": d.roomName,
    "Материал": d.itemName,
    "Количество": d.qty,
    "Себестоимость, ₽": Math.round(d.cost),
    "Логистика, ₽": Math.round(d.logistics),
    "Итого, ₽": Math.round(d.total),
  }));

  downloadWorkbook(
    [
      { name: "Сводка", rows: summaryRows },
      { name: "По объектам", rows: roomRows },
      { name: "По категориям", rows: categoryRows },
      { name: "Детализация", rows: detailRows },
    ],
    `otchet-${periodLabel.replace(/\s+/g, "-")}-${todayISO()}.xlsx`
  );
};

// Выгрузка общескладского инвентаря: текущее распределение по местам плюс
// полный журнал всех перемещений.
const exportAssets = (assets, transfers, objects, warehouses) => {
  const resolveLabel = (key) => {
    if (key === "written_off") return "Списано";
    const wh = warehouses.find((w) => w.id === key);
    if (wh) return wh.name;
    const obj = objects.find((o) => o.number === key);
    if (obj) return `${key} — ${obj.name}`;
    const t = transfers.find((t) => t.fromKey === key || t.toKey === key);
    if (t) return `${key} — ${t.fromKey === key ? t.fromLabel : t.toLabel}`;
    return key;
  };

  const distributionRows = [];
  assets.forEach((asset) => {
    const dist = getAssetDistribution(asset, transfers);
    Object.entries(dist)
      .filter(([, qty]) => qty > 0)
      .forEach(([key, qty]) => {
        distributionRows.push({
          "Инвентарь": asset.name,
          "Местоположение": resolveLabel(key),
          "Количество": qty,
        });
      });
  });

  const transferRows = transfers.map((t) => ({
    "Дата": fmtDate(t.date),
    "Инвентарь": assets.find((a) => a.id === t.assetId)?.name || "—",
    "Откуда": t.fromLabel,
    "Куда": t.toLabel,
    "Количество": t.quantity,
    "Комментарий": t.note || "",
  }));

  downloadWorkbook(
    [
      { name: "Текущее расположение", rows: distributionRows },
      { name: "Журнал перемещений", rows: transferRows },
    ],
    `inventar-${todayISO()}.xlsx`
  );
};

// ---------- роли доступа ----------
