  warehouse: { label: "Сотрудник склада", emoji: "📦", password: "sklad2026", tabs: ["issue", "assets", "lists"], defaultTab: "issue" },
  finance: { label: "Финансовый отдел", emoji: "📊", password: "finotdel2026", tabs: ["report", "prices"], defaultTab: "report" },
