// ---------- Audit log (журнал изменений) ----------

// ---------- Price trends (динамика цен) ----------

function PriceTrendsView({ items, receipts }) {
  const [expandedId, setExpandedId] = useState(null);
  const [filter, setFilter] = useState("");

  // Для каждой позиции — история цен из реальных поступлений (не из
  // справочника вариантов закупки, там могут быть непроверенные цены).
  // Нужно минимум 2 закупки, чтобы вообще было что сравнивать.
  const trends = useMemo(() => {
    return items
      .map((item) => {
        const history = receipts
          .filter((r) => r.itemId === item.id)
          .sort((a, b) => a.date.localeCompare(b.date));
        if (history.length < 2) return null;
        const first = history[0];
        const last = history[history.length - 1];
        const change = ((last.unitCost - first.unitCost) / first.unitCost) * 100;
        return { item, history, first, last, change };
      })
      .filter(Boolean)
      .filter((t) => t.item.name.toLowerCase().includes(filter.toLowerCase()))
      .sort((a, b) => b.change - a.change);
  }, [items, receipts, filter]);

  return (
    <div>
      <div className="wh-header">
        <div>
          <h1>📈 Динамика цен</h1>
          <p className="wh-sub">
            Себестоимость позиций от первой зафиксированной закупки до последней — чтобы вовремя
            замечать, что что-то заметно подорожало
          </p>
        </div>
      </div>

      <div className="wh-search">
        <Search size={16} />
        <input placeholder="Найти по названию" value={filter} onChange={(e) => setFilter(e.target.value)} />
      </div>

      {trends.length === 0 && (
        <div className="wh-empty">
          Пока недостаточно данных. Динамика появится, как только по одной и той же позиции наберётся
          минимум две закупки в «Истории поступлений» — тогда будет с чем сравнивать.
        </div>
      )}

      <div className="wh-price-trend-list">
        {trends.map((t) => {
          const isUp = t.change > 0;
          const isBig = Math.abs(t.change) >= 15;
          const isExpanded = expandedId === t.item.id;
          const maxPoint = Math.max(...t.history.map((h) => h.unitCost));
          return (
            <div className="wh-price-trend-card" key={t.item.id}>
              <button className="wh-price-trend-head" onClick={() => setExpandedId(isExpanded ? null : t.item.id)}>
                <span className="wh-col-name wh-strong">{t.item.name}</span>
                <span className="wh-mono wh-muted">{rub(t.first.unitCost)} → {rub(t.last.unitCost)}</span>
                <span className={`wh-trend-badge ${isUp ? "up" : "down"} ${isBig ? "big" : ""}`}>
                  {isBig && isUp && "⚠️ "}{isUp ? "▲" : "▼"} {Math.abs(Math.round(t.change))}%
                </span>
              </button>
              {isExpanded && (
                <div className="wh-price-trend-history">
                  {t.history.map((r) => (
                    <div className="wh-price-trend-point" key={r.id}>
                      <span className="wh-mono wh-muted">{fmtDate(r.date)}</span>
                      <div className="wh-bar-track">
                        <div className="wh-bar-fill" style={{ width: `${(r.unitCost / maxPoint) * 100}%` }} />
                      </div>
                      <span className="wh-mono wh-strong">{rub(r.unitCost)}</span>
                      <span className="wh-col-name wh-muted">{r.supplier || "—"}</span>
                    </div>
                  ))}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

function AuditLogView({ log, items, onRestoreItem, onRestoreLegacy }) {
  const [filter, setFilter] = useState("");
  const [justRestored, setJustRestored] = useState(() => new Set());
  const [legacyDone, setLegacyDone] = useState(false);

  const filtered = log.filter((entry) => {
    const q = filter.toLowerCase();
    return (
      entry.action.toLowerCase().includes(q) ||
      entry.details.toLowerCase().includes(q) ||
      (entry.by || "").toLowerCase().includes(q) ||
      (ROLES[entry.role]?.label || "").toLowerCase().includes(q)
    );
  });

  const handleRestore = (entry) => {
    onRestoreItem(entry.restorable.data);
    setJustRestored((prev) => new Set(prev).add(entry.id));
  };

  const handleRestoreLegacy = () => {
    onRestoreLegacy();
    setLegacyDone(true);
  };

  return (
    <div>
      <div className="wh-header">
        <div>
          <h1>📝 Журнал изменений</h1>
          <p className="wh-sub">
            Кто и когда менял каталог, объекты, инвентарь и склады — то, что не попадает
            ни в журнал выдач, ни в историю поступлений, ни в журнал перемещений
          </p>
        </div>
      </div>

      <div className="wh-legacy-restore">
        <span>
          🧹 7 позиций категории «Средства для уборки» были удалены ещё до появления кнопки «Восстановить»
          в этом журнале — их снимок для точечного восстановления не сохранился. Можно вернуть их разом.
        </span>
        <button className="wh-btn-ghost" onClick={handleRestoreLegacy} disabled={legacyDone}>
          {legacyDone ? "Возвращено" : "Вернуть 7 позиций"}
        </button>
      </div>

      <div className="wh-search">
        <Search size={16} />
        <input placeholder="Фильтр по действию, роли или деталям" value={filter} onChange={(e) => setFilter(e.target.value)} />
      </div>

      <div className="wh-table">
        <div className="wh-row wh-row-head wh-row-audit">
          <span>Когда</span>
          <span>Кто</span>
          <span className="wh-col-name">Действие</span>
          <span className="wh-col-name">Детали</span>
          <span></span>
        </div>
        {filtered.map((entry) => {
          const canRestoreItem =
            entry.restorable?.type === "item" &&
            !items.some((i) => i.id === entry.restorable.data.id);
          const restored = justRestored.has(entry.id);
          return (
            <div className="wh-row wh-row-audit" key={entry.id}>
              <span className="wh-mono wh-muted">{fmtDateTime(entry.date)}</span>
              <span>
                {entry.by && <strong className="wh-audit-name">{entry.by}</strong>}
                <span className="wh-muted" style={{ fontSize: entry.by ? 11 : undefined }}>
                  {ROLES[entry.role]?.emoji} {ROLES[entry.role]?.label || entry.role}
                </span>
              </span>
              <span className="wh-col-name wh-strong">{entry.action}</span>
              <span className="wh-col-name wh-col-wrap wh-muted" title={entry.details}>{entry.details}</span>
              <span>
                {entry.restorable?.type === "item" && (
                  restored || !canRestoreItem ? (
                    <span className="wh-muted" style={{ fontSize: 11.5 }}>{restored ? "Восстановлено" : "Уже в каталоге"}</span>
                  ) : (
                    <button className="wh-btn-ghost" onClick={() => handleRestore(entry)}>Восстановить</button>
                  )
                )}
              </span>
            </div>
          );
        })}
        {filtered.length === 0 && <div className="wh-empty">{log.length === 0 ? "Изменений пока не было" : "Ничего не найдено"}</div>}
      </div>
    </div>
  );
}

// ---------- Чек-листы ----------
const CHECK_STAGES = [
  { key: "printed", label: "Напечатано" },
  { key: "delivered", label: "Отвезено" },
  { key: "installed", label: "Установлено" },
];

const stagesOf = (c) => (c && c.stages && c.stages.length ? c.stages : CHECK_STAGES);

const STAGE_PRESETS = [
  { name: "Напечатано (общее) + Установлено по квартирам", stock: "Напечатано", text: "Установлено" },
  { name: "Куплено (общее) + Установлено по квартирам", stock: "Куплено", text: "Установлено" },
  { name: "Только отметка по квартирам", stock: "", text: "Установлено" },
];

function ChecklistsView({ checklists, items = [], objects, onCreate, onDelete, onToggle, onSetProduced, onLinkItem, onAddNew, onExclude, onRestore }) {
  const [openId, setOpenId] = useState(null);
  const [newTitle, setNewTitle] = useState("");
  const [onlyOpen, setOnlyOpen] = useState(false);
  const [query, setQuery] = useState("");
  const [confirmDelete, setConfirmDelete] = useState(false);
  const [stagesText, setStagesText] = useState(STAGE_PRESETS[0].text);
  const [stockText, setStockText] = useState(STAGE_PRESETS[0].stock);
  const [showExcluded, setShowExcluded] = useState(false);
  const [newItemId, setNewItemId] = useState("");
  const itemOptions = [...items].sort((a, b) => (a.category === "3D" ? 0 : 1) - (b.category === "3D" ? 0 : 1) || a.name.localeCompare(b.name, "ru"));

  const list = checklists.find((c) => c.id === openId) || null;
  const objById = useMemo(() => Object.fromEntries(objects.map((o) => [o.id, o])), [objects]);

  const isDone = (c, oid) => {
    const m = c.marks[oid] || {};
    return stagesOf(c).every((st) => m[st.key]);
  };

  const sortObjs = (arr) => [...arr].sort((a, b) => (a.number || "").localeCompare(b.number || "", "ru", { numeric: true }));

  const create = () => {
    const labels = stagesText.split(",").map((x) => x.trim()).filter(Boolean).slice(0, 5);
    if (labels.length === 0) return;
    const id = onCreate(newTitle, labels, stockText, newItemId);
    if (id) { setNewTitle(""); setNewItemId(""); setOpenId(id); }
  };

  // ----- список чек-листов -----
  if (!list) {
    return (
      <div>
        <div className="wh-panel" style={{ marginBottom: 14 }}>
          <h2 style={{ margin: "0 0 4px", fontSize: 17 }}>Чек-листы по объектам</h2>
          <p style={{ margin: "0 0 12px", color: "var(--muted)", fontSize: 13 }}>
            Для разовых поставок в квартиры: баночки для чая, рамки, тапочки и т.п. Список объектов подставится сам. «Напечатано/куплено» ведётся общим числом, а по квартирам отмечается только «Установлено».
          </p>
          <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
            <input
              className="wh-search"
              style={{ width: "100%", boxSizing: "border-box", padding: "11px 14px" }}
              placeholder="Название, например: Баночка для чая"
              value={newTitle}
              onChange={(e) => setNewTitle(e.target.value)}
              onKeyDown={(e) => { if (e.key === "Enter") create(); }}
            />
            <div style={{ fontSize: 12.5, color: "var(--muted)" }}>Как вести чек-лист:</div>
            <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
              {STAGE_PRESETS.map((pr) => (
                <button
                  key={pr.text}
                  type="button"
                  onClick={() => { setStagesText(pr.text); setStockText(pr.stock); }}
                  style={{ flexShrink: 0, whiteSpace: "nowrap", cursor: "pointer", padding: "7px 12px", borderRadius: 999, fontSize: 12.5, fontWeight: 600, border: "none", background: stagesText === pr.text && stockText === pr.stock ? "var(--indigo)" : "#fff", color: stagesText === pr.text && stockText === pr.stock ? "#fff" : "var(--text)" }}
                >
                  {pr.name}
                </button>
              ))}
            </div>
            <input
              className="wh-search"
              style={{ width: "100%", boxSizing: "border-box", padding: "11px 14px" }}
              placeholder="Общий счётчик (необязательно): Напечатано, Куплено…"
              value={stockText}
              onChange={(e) => setStockText(e.target.value)}
            />
            <input
              className="wh-search"
              style={{ width: "100%", boxSizing: "border-box", padding: "11px 14px" }}
              placeholder="Этапы по каждой квартире через запятую, например: Отвезено, Установлено"
              value={stagesText}
              onChange={(e) => setStagesText(e.target.value)}
            />
            <div style={{ fontSize: 12.5, color: "var(--muted)" }}>
              Связать с позицией каталога (необязательно): когда вы выдадите её на объект, квартира в чек-листе отметится сама.
            </div>
            <select
              value={newItemId}
              onChange={(e) => setNewItemId(e.target.value)}
              style={{ width: "100%", boxSizing: "border-box", padding: "11px 14px", borderRadius: 12, border: "1.5px solid var(--muted-2)", background: "#fff", fontSize: 14 }}
            >
              <option value="">Не связывать — отмечать вручную</option>
              {itemOptions.map((it) => (<option key={it.id} value={it.id}>{it.name}{it.category === "3D" ? " (3D)" : ""}</option>))}
            </select>
            <button type="button" className="wh-btn-primary" style={{ justifyContent: "center" }} onClick={create} disabled={!newTitle.trim() || !stagesText.trim()}>
              <Plus size={15} /> Создать чек-лист
            </button>
          </div>
        </div>

        {checklists.length === 0 && (
          <div className="wh-panel" style={{ color: "var(--muted)", fontSize: 13.5 }}>Пока нет ни одного чек-листа.</div>
        )}

        {checklists.map((c) => {
          const total = c.objectIds.length;
          const done = c.objectIds.filter((oid) => isDone(c, oid)).length;
          const fresh = objects.filter((o) => o.active !== false && !c.objectIds.includes(o.id) && !(c.excluded || []).includes(o.id)).length;
          return (
            <button
              key={c.id}
              type="button"
              className="wh-panel"
              onClick={() => { setOpenId(c.id); setOnlyOpen(false); setQuery(""); setConfirmDelete(false); }}
              style={{ display: "block", width: "100%", textAlign: "left", cursor: "pointer", marginBottom: 10, border: fresh ? "2px solid #F5A524" : undefined }}
            >
              <div style={{ fontWeight: 700, fontSize: 15 }}>📋 {c.title}</div>
              <div style={{ color: "var(--muted)", fontSize: 12.5, margin: "4px 0 8px" }}>
                Готово полностью: {done} из {total} · создал(а) {c.createdBy || "—"}, {fmtDateTime(c.createdAt)}
              </div>
              <div style={{ height: 8, borderRadius: 99, background: "var(--line)", overflow: "hidden" }}>
                <div style={{ height: "100%", width: `${total ? (done / total) * 100 : 0}%`, background: "var(--pos)" }} />
              </div>
              {fresh > 0 && (
                <div style={{ marginTop: 8, color: "#B26A00", fontWeight: 600, fontSize: 13 }}>
                  ⚠️ Новых объектов без этой позиции: {fresh}
                </div>
              )}
            </button>
          );
        })}
      </div>
    );
  }

  // ----- один чек-лист -----
  const missing = sortObjs(objects.filter((o) => o.active !== false && !list.objectIds.includes(o.id) && !(list.excluded || []).includes(o.id)));
  const excludedObjs = sortObjs((list.excluded || []).map((id) => objById[id]).filter(Boolean));
  const inList = sortObjs(list.objectIds.map((id) => objById[id]).filter(Boolean));
  const total = inList.length;
  const done = inList.filter((o) => isDone(list, o.id)).length;
  const q = query.trim().toLowerCase();
  const shown = inList.filter((o) => {
    if (onlyOpen && isDone(list, o.id)) return false;
    if (q && !`${o.number} ${o.name}`.toLowerCase().includes(q)) return false;
    return true;
  });
  const stages = stagesOf(list);
  const stageCount = (key) => inList.filter((o) => (list.marks[o.id] || {})[key]).length;

  const exportXlsx = () => {
    const rows = sortObjs([...inList]).map((o) => {
      const m = list.marks[o.id] || {};
      const row = { "№": o.number, "Объект": o.name, "Статус": o.active === false ? "неактивен" : "" };
      stages.forEach((st) => {
        row[st.label] = m[st.key] ? "да" : "";
        row[`${st.label} — кто, когда`] = m[st.key] ? `${m[st.key].by || ""} ${fmtDateTime(m[st.key].at)}` : "";
      });
      return row;
    });
    missing.forEach((o) => rows.push({ "№": o.number, "Объект": o.name, "Статус": "НОВЫЙ — не добавлен в чек-лист" }));
    const sheets = [{ name: "Чек-лист", rows }];
    if (list.stockLabel) {
      sheets.push({
        name: "Итого",
        rows: [{
          [`${list.stockLabel} всего`]: list.produced || 0,
          [stages[0]?.label || "Установлено"]: stageCount(stages[0]?.key),
          "Осталось на руках": (list.produced || 0) - stageCount(stages[0]?.key),
        }],
      });
    }
    downloadWorkbook(sheets, `chek-list-${todayISO()}.xlsx`);
  };

  return (
    <div>
      <button type="button" className="wh-btn-ghost" style={{ marginBottom: 10 }} onClick={() => setOpenId(null)}>
        ← Все чек-листы
      </button>

      <div className="wh-panel" style={{ marginBottom: 12 }}>
        <div style={{ display: "flex", justifyContent: "space-between", gap: 8, alignItems: "flex-start" }}>
          <h2 style={{ margin: 0, fontSize: 17 }}>📋 {list.title}</h2>
          <button type="button" className="wh-btn-ghost" title="Скачать в Excel" aria-label="Скачать в Excel" onClick={exportXlsx} style={{ flexShrink: 0 }}>
            <FileSpreadsheet size={16} />
          </button>
        </div>
        <div style={{ color: "var(--muted)", fontSize: 12.5, margin: "6px 0 8px" }}>
          Полностью готово: <b>{done}</b> из <b>{total}</b>
        </div>
        <div style={{ height: 8, borderRadius: 99, background: "var(--line)", overflow: "hidden" }}>
          <div style={{ height: "100%", width: `${total ? (done / total) * 100 : 0}%`, background: "var(--pos)" }} />
        </div>
        <div style={{ display: "flex", flexWrap: "wrap", gap: 12, marginTop: 8, fontSize: 12.5, color: "var(--muted)" }}>
          {stages.map((st) => (<span key={st.key}>{st.label}: <b>{stageCount(st.key)}</b></span>))}
        </div>
        {list.stockLabel && (() => {
          const produced = list.produced || 0;
          const out = stages.length ? stageCount(stages[0].key) : 0;
          const left = produced - out;
          return (
            <div style={{ marginTop: 12, paddingTop: 12, borderTop: "1px solid var(--line)" }}>
              <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
                <span style={{ fontWeight: 600, fontSize: 14 }}>{list.stockLabel} всего:</span>
                <button type="button" aria-label="Меньше" onClick={() => onSetProduced(list.id, produced - 1)} style={{ flexShrink: 0, width: 34, height: 34, borderRadius: 999, border: "none", background: "var(--line)", cursor: "pointer", fontSize: 18, lineHeight: 1 }}>−</button>
                <input
                  type="number"
                  min="0"
                  value={produced}
                  onChange={(e) => onSetProduced(list.id, e.target.value)}
                  style={{ width: 70, textAlign: "center", padding: "8px 6px", borderRadius: 10, border: "1.5px solid var(--muted-2)", fontSize: 15, fontWeight: 700 }}
                />
                <button type="button" aria-label="Больше" onClick={() => onSetProduced(list.id, produced + 1)} style={{ flexShrink: 0, width: 34, height: 34, borderRadius: 999, border: "none", background: "var(--indigo)", color: "#fff", cursor: "pointer", fontSize: 18, lineHeight: 1 }}>+</button>
              </div>
              <div style={{ marginTop: 8, fontSize: 13, color: left < 0 ? "var(--neg)" : "var(--muted)" }}>
                {stages[0]?.label || "Установлено"}: <b>{out}</b> · Осталось на руках: <b>{left}</b>
                {left < 0 && " — установлено больше, чем указано в счётчике, поправьте число выше"}
              </div>
            </div>
          );
        })()}
      </div>

      <div className="wh-panel" style={{ marginBottom: 12, padding: 12 }}>
        <div style={{ fontSize: 12.5, color: "var(--muted)", marginBottom: 6 }}>
          Связано с позицией каталога — выдача её на объект сама ставит «{stages[stages.length - 1]?.label}»:
        </div>
        <select
          value={list.itemId || ""}
          onChange={(e) => onLinkItem(list.id, e.target.value)}
          style={{ width: "100%", boxSizing: "border-box", padding: "10px 12px", borderRadius: 12, border: "1.5px solid var(--muted-2)", background: "#fff", fontSize: 14 }}
        >
          <option value="">Не связано — отмечаю вручную</option>
          {itemOptions.map((it) => (<option key={it.id} value={it.id}>{it.name}{it.category === "3D" ? " (3D)" : ""}</option>))}
        </select>
      </div>

      {missing.length > 0 && (
        <div style={{ background: "#FFF4DC", border: "2px solid #F5A524", borderRadius: 14, padding: 14, marginBottom: 12 }}>
          <div style={{ fontWeight: 700, color: "#8A5200", marginBottom: 6 }}>
            ⚠️ Новые объекты — в этом чек-листе их ещё нет ({missing.length})
          </div>
          <div style={{ fontSize: 13, color: "#8A5200", marginBottom: 10, lineHeight: 1.5 }}>
            {missing.map((o) => `${o.number} ${o.name}`).join(", ")}
          </div>
          <button type="button" className="wh-btn-primary" onClick={() => onAddNew(list.id)}>
            <Plus size={15} /> Добавить в чек-лист
          </button>
        </div>
      )}

      <div style={{ display: "flex", flexDirection: "column", gap: 10, marginBottom: 12 }}>
        <input
          className="wh-search"
          style={{ width: "100%", boxSizing: "border-box", padding: "11px 14px" }}
          placeholder="Найти объект"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
        />
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
          <button type="button" onClick={() => setOnlyOpen(false)} style={{ flexShrink: 0, whiteSpace: "nowrap", cursor: "pointer", padding: "8px 14px", borderRadius: 999, fontSize: 13, fontWeight: 600, border: "none", background: !onlyOpen ? "var(--indigo)" : "#fff", color: !onlyOpen ? "#fff" : "var(--text)" }}>Все</button>
          <button type="button" onClick={() => setOnlyOpen(true)} style={{ flexShrink: 0, whiteSpace: "nowrap", cursor: "pointer", padding: "8px 14px", borderRadius: 999, fontSize: 13, fontWeight: 600, border: "none", background: onlyOpen ? "var(--indigo)" : "#fff", color: onlyOpen ? "#fff" : "var(--text)" }}>Только не сделано</button>
        </div>
      </div>

      {shown.length === 0 && (
        <div className="wh-panel" style={{ color: "var(--muted)", fontSize: 13.5 }}>
          {onlyOpen && !q ? "Всё сделано 🎉" : "Ничего не найдено."}
        </div>
      )}

      {shown.map((o) => {
        const m = list.marks[o.id] || {};
        const full = isDone(list, o.id);
        return (
          <div key={o.id} className="wh-panel" style={{ marginBottom: 8, padding: 12, background: full ? "#EAFBF3" : undefined }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 8, marginBottom: 8 }}>
              <div style={{ fontWeight: 600, fontSize: 14 }}>
                {full ? "✅ " : ""}{o.number} · {o.name}
                {o.active === false && <span style={{ color: "var(--muted)", fontWeight: 400 }}> (неактивен)</span>}
              </div>
              <button
                type="button"
                title="Убрать объект из этого чек-листа"
                aria-label="Убрать объект из этого чек-листа"
                onClick={() => onExclude(list.id, o.id)}
                style={{ flexShrink: 0, width: 30, height: 30, borderRadius: 999, border: "none", background: "var(--line)", color: "var(--muted)", cursor: "pointer", display: "inline-flex", alignItems: "center", justifyContent: "center" }}
              >
                <X size={15} />
              </button>
            </div>
            <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
              {stages.map((st) => {
                const mark = m[st.key];
                return (
                  <button
                    key={st.key}
                    type="button"
                    onClick={() => onToggle(list.id, o.id, st.key)}
                    title={mark ? `${mark.by || ""} · ${fmtDateTime(mark.at)}` : ""}
                    style={{
                      flexShrink: 0, whiteSpace: "nowrap", cursor: "pointer",
                      padding: "8px 12px", borderRadius: 999, fontSize: 13, fontWeight: 600,
                      border: mark ? "1.5px solid var(--pos)" : "1.5px solid var(--muted-2)",
                      background: mark ? "var(--pos)" : "#fff",
                      color: mark ? "#fff" : "var(--text)",
                    }}
                  >
                    {mark ? "✓ " : ""}{st.label}
                  </button>
                );
              })}
            </div>
            {stages.some((st) => m[st.key]) && (
              <div style={{ marginTop: 6, fontSize: 11.5, color: "var(--muted)", lineHeight: 1.5 }}>
                {stages.filter((st) => m[st.key]).map((st) => `${st.label}: ${m[st.key].by || "—"}, ${fmtDateTime(m[st.key].at)}${m[st.key].auto ? " (из выдачи)" : ""}`).join(" · ")}
              </div>
            )}
          </div>
        );
      })}

      {excludedObjs.length > 0 && (
        <div style={{ marginTop: 16 }}>
          <button type="button" className="wh-btn-ghost" onClick={() => setShowExcluded((v) => !v)}>
            {showExcluded ? "Скрыть" : "Показать"} убранные из списка ({excludedObjs.length})
          </button>
          {showExcluded && excludedObjs.map((o) => (
            <div key={o.id} className="wh-panel" style={{ marginTop: 8, padding: 12, opacity: 0.8, display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8 }}>
              <span style={{ fontSize: 14 }}>{o.number} · {o.name}</span>
              <button type="button" className="wh-btn-ghost" style={{ flexShrink: 0 }} onClick={() => onRestore(list.id, o.id)}>Вернуть</button>
            </div>
          ))}
        </div>
      )}

      <div style={{ marginTop: 16 }}>
        {!confirmDelete ? (
          <button type="button" className="wh-btn-ghost" onClick={() => setConfirmDelete(true)}>
            <Trash2 size={14} /> Удалить чек-лист
          </button>
        ) : (
          <div className="wh-inline-confirm">
            <span>Удалить «{list.title}» вместе со всеми отметками?</span>
            <button type="button" className="wh-btn-primary" onClick={() => { onDelete(list.id); setOpenId(null); }}>Да, удалить</button>
            <button type="button" className="wh-btn-ghost" onClick={() => setConfirmDelete(false)}>Отмена</button>
          </div>
        )}
      </div>
    </div>
  );
}

const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Poppins:wght@500;600;700;800&family=Inter:wght@400;500;600;700&display=swap');

/* Коренной фикс "расползания страницы вширь" на мобильном — а не починка
   каждого отдельного места по одному. У flex/grid-элементов браузер по
   умолчанию не даёт им сжиматься меньше их содержимого (min-width: auto) —
   из-за этого один длинный текст где угодно в приложении мог раздвинуть
   всю страницу и сломать масштаб, независимо от overflow на предках.
   Здесь сбрасываем это умолчание для вообще всех элементов приложения —
   а те немногие места, которым специально нужна более широкая минимальная
   ширина (прокручиваемые таблицы), задают её явно своим собственным,
   более специфичным правилом ниже, и оно всё равно победит. */
.wh-root * { min-width: 0; }

.wh-root {
  --bg:#EEF2F8;
  --white:#FFFFFF;
  --text:#232A3B;
  --muted:#94A0B8;
  --muted-2:#B4BECF;
  --line:#EEF1F6;

  --indigo:#5B6EF5;
  --indigo-dark:#4551D6;

  --orange-1:#FDBB53; --orange-2:#F58B6B;
  --blue-1:#6E86FF; --blue-2:#4A5FE0;
  --cyan-1:#3FD0E0; --cyan-2:#1FA9C4;
  --green-1:#54E0AA; --green-2:#22BF8B;
  --hero-1:#63E6B7; --hero-2:#2FAE8C;

  --pos:#22BF8B;
  --neg:#F0654F;

  --shadow-lg:0 24px 48px -16px rgba(35,42,59,0.14);
  --shadow-md:0 14px 32px -12px rgba(35,42,59,0.10);
  --shadow-sm:0 8px 18px -8px rgba(35,42,59,0.10);

  background: var(--bg);
  color: var(--text);
  font-family: 'Inter', sans-serif;
  font-size: 14px;
  line-height: 1.45;
  min-height: 100vh;
  width: 100%;
  max-width: 100vw;
  box-sizing: border-box;
  padding: 24px 20px 40px;
  overflow-x: clip;
  -webkit-font-smoothing: antialiased;
}

/* На мобильном браузере, если хоть один элемент где-то в глубине верстки
   чуть шире экрана (например, строка таблицы, которая должна прокручиваться
   внутри своего блока), Safari иногда расширяет масштаб всей страницы вместо
   того чтобы просто обрезать этот элемент — тогда при открытии всё выглядит
   "увеличенным", и приходится вручную разводить пальцы, чтобы вернуть
   нормальный масштаб. overflow-x: clip надёжнее, чем hidden, против именно
   этого поведения (hidden в некоторых версиях Safari всё равно позволяет
   внутреннему широкому элементу повлиять на начальный масштаб страницы). */
html, body, #root {
  -webkit-text-size-adjust: 100%; text-size-adjust: 100%;
  margin: 0;
  min-height: 100%;
  width: 100%;
  max-width: 100vw;
  overflow-x: clip;
  background: #EEF2F8;
}

.wh-page { max-width: 1180px; margin: 0 auto; }

.wh-save-error {
  display: flex; align-items: center; gap: 9px;
  background: #FDEDEA; color: #A83A26; border: 1px solid #F3C4B8;
  border-radius: 14px; padding: 12px 16px; margin-bottom: 16px;
  font-size: 12.5px; font-weight: 600; line-height: 1.5;
}

.wh-legacy-restore {
  display: flex; align-items: center; gap: 14px; justify-content: space-between; flex-wrap: wrap;
  background: #F6F8FC; border: 1px solid var(--line);
  border-radius: 14px; padding: 12px 16px; margin-bottom: 18px;
  font-size: 12.5px; color: var(--text); line-height: 1.5;
}
.wh-legacy-restore span { max-width: 560px; }
.wh-legacy-restore .wh-btn-ghost:disabled { opacity: .5; cursor: default; }

/* ---- login gate ---- */
.wh-login-root { display: flex; align-items: center; justify-content: center; padding: 40px 20px; }
.wh-login-card {
  background: var(--white); border-radius: 26px; box-shadow: var(--shadow-lg);
  padding: 36px 34px 30px; width: 100%; max-width: 340px;
  display: flex; flex-direction: column; align-items: center; text-align: center;
}
.wh-login-logo { width: 56px; height: 56px; border-radius: 16px; overflow: hidden; box-shadow: var(--shadow-sm); margin-bottom: 18px; }
.wh-login-logo img { width: 100%; height: 100%; object-fit: cover; display: block; }
.wh-login-title { font-family: 'Poppins', sans-serif; font-weight: 700; font-size: 17px; margin-bottom: 4px; }
.wh-login-sub { font-size: 12.5px; color: var(--muted); font-weight: 500; margin-bottom: 24px; }
.wh-login-field { display: flex; flex-direction: column; gap: 6px; font-size: 12.5px; color: var(--muted); font-weight: 600; width: 100%; text-align: left; margin-bottom: 14px; }
.wh-login-field select, .wh-login-field input {
  font: inherit; font-size: 13.5px; color: var(--text); font-family: 'Inter', sans-serif;
  border: 1px solid var(--line); border-radius: 12px; padding: 10px 12px; background: #F9FAFD;
}
.wh-login-field select:focus, .wh-login-field input:focus { outline: 2px solid var(--indigo); outline-offset: 0; border-color: var(--indigo); }
.wh-login-error { color: var(--neg); font-size: 12.5px; font-weight: 600; margin-bottom: 14px; }
.wh-login-submit { width: 100%; justify-content: center; margin-top: 6px; }

.wh-mono { font-family: 'Inter', sans-serif; font-variant-numeric: tabular-nums; font-size: 13px; }
.wh-muted { color: var(--muted); }
.wh-strong { font-weight: 700; }

/* ---- hero sheet ---- */
.wh-hero-sheet { position: relative; background: var(--white); border-radius: 26px; box-shadow: var(--shadow-lg); padding: 22px 24px 24px; margin-bottom: 18px; }

/* Верхний ряд: бренд слева, кто вошёл — справа. Всегда вместе, независимо
   от того, сколько вкладок в разделе ниже и как они переносятся. */
.wh-hero-top-row { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 14px; margin-bottom: 16px; }

.wh-hero-nav { display: flex; align-items: center; flex-wrap: wrap; gap: 14px; }
.wh-brand { display: flex; align-items: center; gap: 10px; }
.wh-brand-badge {
  width: 36px; height: 36px; border-radius: 11px;
  background: #EEF0FF; color: var(--indigo-dark);
  display: flex; align-items: center; justify-content: center;
  box-shadow: var(--shadow-sm); flex-shrink: 0;
  overflow: hidden;
}
.wh-brand-badge img { width: 100%; height: 100%; object-fit: cover; display: block; }
.wh-brand-title { font-family: 'Poppins', sans-serif; font-weight: 700; font-size: 15px; line-height: 1.2; }
.wh-brand-sub { font-size: 11.5px; color: var(--muted); font-weight: 500; margin-top: 2px; }

/* Обёртка вкладок — растягивается на всё оставшееся место и режет
   переполнение, чтобы затухающий край подсказывал: тут можно листать вбок. */
.wh-tab-pill-wrap { position: relative; flex: 1 1 auto; min-width: 0; overflow: hidden; border-radius: 999px; }
.wh-tab-pill-wrap::after {
  content: ""; position: absolute; top: 0; right: 0; bottom: 0; width: 28px;
  background: linear-gradient(to right, rgba(246,248,252,0), #F6F8FC 80%);
  pointer-events: none;
}
.wh-tab-pill { display: inline-flex; gap: 4px; background: #F6F8FC; border-radius: 999px; padding: 4px; max-width: 100%; overflow-x: auto; }
.wh-tab-pill button {
  border: none; background: transparent; cursor: pointer; flex-shrink: 0;
  font-family: 'Inter', sans-serif; font-weight: 600; font-size: 13px;
  padding: 9px 16px; border-radius: 999px; color: var(--muted); white-space: nowrap;
  transition: background .15s ease, color .15s ease;
}
.wh-tab-pill button:hover { color: var(--indigo-dark); }
.wh-tab-pill button.active { background: var(--indigo); color: #fff; box-shadow: var(--shadow-sm); }

/* Бейдж роли — обычный элемент верхнего ряда (не "плавающий" поверх). */
.wh-role-badge {
  display: inline-flex; align-items: center; gap: 10px; font-size: 12.5px; color: var(--text); font-weight: 600;
  background: #F6F8FC; border-radius: 999px; padding: 7px 8px 7px 14px;
  flex-shrink: 0;
}
.wh-logout-btn { border: none; background: #fff; color: var(--muted); font: inherit; font-size: 11.5px; font-weight: 600; padding: 6px 12px; border-radius: 999px; cursor: pointer; box-shadow: var(--shadow-sm); }
.wh-logout-btn:hover { color: var(--neg); }

/* ---- wallet cards ---- */
.wh-wallet-row { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; margin-bottom: 20px; }
.wh-wallet-card {
  border-radius: 20px; padding: 20px 20px 22px; color: #fff; box-shadow: var(--shadow-md);
  position: relative; overflow: hidden;
  border: none; text-align: left; font-family: inherit; cursor: pointer;
  display: block; width: 100%;
  transition: transform .15s ease, box-shadow .15s ease;
}
.wh-wallet-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-lg); }
.wh-wallet-card:active { transform: translateY(0); }
.wh-wallet-card.orange { background: linear-gradient(145deg, var(--orange-1), var(--orange-2)); }
.wh-wallet-card.blue { background: linear-gradient(145deg, var(--blue-1), var(--blue-2)); }
.wh-wallet-card.cyan { background: linear-gradient(145deg, var(--cyan-1), var(--cyan-2)); }
.wh-wallet-card.green { background: linear-gradient(145deg, var(--green-1), var(--green-2)); }
.wh-wallet-icon { font-size: 19px; width: 38px; height: 38px; border-radius: 12px; background: rgba(255,255,255,0.28); display: flex; align-items: center; justify-content: center; margin-bottom: 18px; }
.wh-wallet-card .w-label { font-size: 12.5px; font-weight: 600; opacity: .92; margin-bottom: 10px; }
.wh-wallet-card .w-value { font-size: 19px; font-weight: 700; font-family: 'Poppins', sans-serif; margin-bottom: 4px; }
.wh-wallet-card .w-sub { font-size: 11px; opacity: .85; font-weight: 500; }

/* ---- main ---- */
.wh-main { }

.wh-header { display: flex; justify-content: space-between; align-items: flex-end; gap: 16px; margin-bottom: 18px; flex-wrap: wrap; }
.wh-header h1 { font-family: 'Poppins', sans-serif; font-size: 20px; font-weight: 700; margin: 0 0 4px; }
.wh-sub { color: var(--muted); font-size: 13px; margin: 0; font-weight: 500; }
h2 { font-family: 'Poppins', sans-serif; font-size: 15px; font-weight: 600; margin: 0 0 14px; color: var(--text); }

.wh-btn-primary {
  display: inline-flex; align-items: center; gap: 7px;
  background: var(--indigo); color: #fff; border: none;
  font-family: 'Inter', sans-serif; font-weight: 600; font-size: 13.5px;
  padding: 11px 18px; border-radius: 999px; cursor: pointer;
  box-shadow: var(--shadow-sm);
  transition: background .15s ease; white-space: nowrap;
}
.wh-btn-primary:hover { background: var(--indigo-dark); }
.wh-btn-primary:disabled { opacity: .4; cursor: not-allowed; box-shadow: none; }

.wh-btn-ghost {
  background: transparent; border: 1px solid var(--line); color: var(--text);
  font-family: 'Inter', sans-serif; font-weight: 500; font-size: 13.5px;
  padding: 11px 18px; border-radius: 999px; cursor: pointer;
}

.wh-btn-icon-export {
  display: inline-flex; align-items: center; justify-content: center;
  width: 42px; height: 42px; flex-shrink: 0;
  background: #E9F7EF; border: 1px solid #BFE8CE; color: #1E7A44;
  border-radius: 999px; cursor: pointer; box-shadow: var(--shadow-sm);
  transition: background .15s ease, transform .15s ease;
}
.wh-btn-icon-export:hover { background: #DAF1E3; transform: translateY(-1px); }
.wh-btn-icon-export:active { transform: translateY(0); }

.wh-header-actions { display: flex; gap: 10px; flex-wrap: wrap; }
.wh-header-actions > * { flex-shrink: 0; }
.wh-btn-secondary {
  display: inline-flex; align-items: center; gap: 7px;
  background: #EEF0FF; color: var(--indigo-dark); border: none;
  font-family: 'Inter', sans-serif; font-weight: 600; font-size: 13.5px;
  padding: 11px 18px; border-radius: 999px; cursor: pointer;
  white-space: nowrap;
}
.wh-btn-secondary:hover { background: #E4E9FB; }

.wh-btn-writeoff {
  display: inline-flex; align-items: center; gap: 7px;
  background: #FDEDEA; color: var(--neg); border: none;
  font-family: 'Inter', sans-serif; font-weight: 600; font-size: 13.5px;
  padding: 11px 18px; border-radius: 999px; cursor: pointer; white-space: nowrap;
}
.wh-btn-writeoff:hover { background: #FBDFD9; }
.wh-btn-writeoff-submit {
  display: inline-flex; align-items: center; gap: 7px;
  background: var(--neg); color: #fff; border: none;
  font-family: 'Inter', sans-serif; font-weight: 600; font-size: 13.5px;
  padding: 11px 18px; border-radius: 999px; cursor: pointer;
}
.wh-btn-writeoff-submit:hover { background: #D6553F; }

.wh-inline-confirm {
  display: inline-flex; align-items: center; gap: 10px;
  background: #FDEDEA; border-radius: 999px; padding: 8px 8px 8px 16px;
  font-size: 12.5px; font-weight: 600; color: var(--neg);
}
.wh-inline-confirm-tight { padding: 4px 4px 4px 10px; gap: 6px; font-size: 12px; }
.wh-inline-confirm .wh-btn-writeoff-submit, .wh-inline-confirm .wh-btn-ghost { padding: 6px 12px; font-size: 12px; }

.wh-search {
  display: flex; align-items: center; gap: 8px;
  background: #F6F8FC; border: 1px solid var(--line);
  border-radius: 999px; padding: 10px 16px; margin-bottom: 18px;
  color: var(--muted); max-width: 420px;
}
.wh-search input { border: none; outline: none; background: transparent; font: inherit; color: var(--text); width: 100%; font-family: 'Inter', sans-serif; }
.wh-search-small { max-width: 280px; padding: 7px 12px; margin-bottom: 0; }

.wh-filter-chip {
  display: inline-flex; align-items: center; gap: 8px;
  background: #EEF0FF; color: var(--indigo-dark); font-size: 12.5px; font-weight: 600;
  padding: 7px 8px 7px 14px; border-radius: 999px; margin-bottom: 18px;
}
.wh-filter-chip button { border: none; background: rgba(255,255,255,0.6); color: var(--indigo-dark); border-radius: 999px; width: 20px; height: 20px; display: inline-flex; align-items: center; justify-content: center; cursor: pointer; }
.wh-filter-chip button:hover { background: #fff; }
.wh-filter-chip.warn { background: #FDEDEA; color: var(--neg); }
.wh-filter-chip.warn button { color: var(--neg); }

/* ---- panel / form ---- */
.wh-panel { width: 100%; max-width: 100%; box-sizing: border-box; background: var(--white); border-radius: 22px; box-shadow: var(--shadow-sm); padding: 22px 24px; margin-bottom: 22px; }
.wh-panel-static { margin-bottom: 30px; }
.wh-panel-title { display: flex; justify-content: space-between; align-items: center; font-family: 'Poppins', sans-serif; font-weight: 600; font-size: 14.5px; margin-bottom: 16px; }
.wh-panel-title-icon { display: inline-flex; align-items: center; gap: 8px; }
.wh-panel-accent { box-shadow: var(--shadow-sm), 0 0 0 2px var(--orange-2) inset; }

.wh-receive-toggle { display: inline-flex; gap: 4px; background: #F6F8FC; border-radius: 999px; padding: 4px; margin-bottom: 16px; }
.wh-receive-toggle button { border: none; background: transparent; font: inherit; font-size: 12.5px; font-weight: 600; padding: 8px 16px; border-radius: 999px; cursor: pointer; color: var(--muted); }
.wh-receive-toggle button.active { background: var(--indigo); color: #fff; }

.wh-hint-banner { background: #F6F8FC; border: 1px solid var(--line); border-radius: 14px; padding: 12px 16px; margin-bottom: 16px; font-size: 12.5px; color: var(--text); line-height: 1.5; }

.wh-price-history { background: #F6F8FC; border: 1px solid var(--line); border-radius: 14px; padding: 12px 14px; display: flex; flex-direction: column; gap: 6px; }
.wh-price-history-title { font-size: 11.5px; color: var(--muted); font-weight: 600; margin-bottom: 2px; }
.wh-price-history-row { display: grid; grid-template-columns: 80px 1fr auto; gap: 10px; align-items: center; font-size: 12.5px; }

.wh-cost-calc { background: #FFF7E8; border: 1px dashed var(--orange-2); border-radius: 14px; padding: 12px 16px; margin-top: 14px; display: flex; flex-direction: column; gap: 6px; }

.wh-price-warning {
  display: flex; align-items: flex-start; gap: 10px;
  background: #FDEDEA; border: 1px solid #F3C4B8; color: #A83A26;
  border-radius: 14px; padding: 12px 16px; margin-top: 14px;
  font-size: 12.5px; line-height: 1.5;
}
.wh-price-warning strong { font-family: 'Poppins', sans-serif; }
.wh-audit-name { display: block; font-family: 'Poppins', sans-serif; font-size: 12.5px; margin-bottom: 1px; }
.wh-by-name { display: block; font-size: 10px; color: var(--muted-2); font-weight: 500; }

/* ---- price trends ---- */
.wh-price-trend-list { display: flex; flex-direction: column; gap: 10px; }
.wh-price-trend-card { background: var(--white); border-radius: 16px; box-shadow: var(--shadow-sm); overflow: hidden; }
.wh-price-trend-head {
  display: grid; grid-template-columns: 1.6fr 160px 110px; align-items: center; gap: 14px;
  width: 100%; border: none; background: transparent; cursor: pointer;
  padding: 16px 18px; font-family: inherit; text-align: left;
}
.wh-price-trend-head:hover { background: #F9FAFD; }
.wh-trend-badge {
  display: inline-flex; align-items: center; justify-content: center; gap: 4px;
  font-family: 'Poppins', sans-serif; font-weight: 700; font-size: 12.5px;
  padding: 6px 12px; border-radius: 999px; justify-self: end;
}
.wh-trend-badge.up { background: #FDEDEA; color: var(--neg); }
.wh-trend-badge.down { background: #E3F7EE; color: var(--pos); }
.wh-trend-badge.big.up { background: var(--neg); color: #fff; }

.wh-price-trend-history { padding: 4px 18px 16px; display: flex; flex-direction: column; gap: 8px; border-top: 1px solid var(--line); padding-top: 14px; }
.wh-price-trend-point { display: grid; grid-template-columns: 90px 1fr 90px 1.2fr; align-items: center; gap: 12px; font-size: 12.5px; }
.wh-cost-calc-row { display: flex; justify-content: space-between; gap: 16px; font-size: 12.5px; color: #9A5B12; }
.wh-cost-calc-row span:first-child { max-width: 70%; }

.wh-form-grid { display: grid; grid-template-columns: 1fr; gap: 14px; }
.wh-span-2 { grid-column: span 2; }
.wh-form-grid label, .wh-form-grid .wh-field-block { display: flex; flex-direction: column; gap: 5px; font-size: 12.5px; color: var(--muted); font-weight: 600; }
.wh-form-grid input, .wh-form-grid select {
  font: inherit; font-size: 13.5px; color: var(--text); font-family: 'Inter', sans-serif;
  border: 1px solid var(--line); border-radius: 12px; padding: 9px 12px; background: #F9FAFD;
}
.wh-form-grid input:focus, .wh-form-grid select:focus { outline: 2px solid var(--indigo); outline-offset: 0; border-color: var(--indigo); }

.wh-panel-actions { display: flex; justify-content: space-between; align-items: center; margin-top: 18px; gap: 12px; flex-wrap: wrap; }
.wh-cost-preview { font-size: 13.5px; }
.wh-warning-line { display: flex; align-items: center; gap: 7px; color: var(--neg); font-size: 13px; margin-top: 12px; font-weight: 600; }

/* ---- catalog table ---- */
.wh-cat-block { margin-bottom: 18px; }
.wh-cat-header {
  display: flex; align-items: center; gap: 8px; width: 100%;
  background: transparent; border: none; cursor: pointer;
  padding: 10px 6px; font-family: inherit; color: var(--text);
}
.wh-cat-name { font-family: 'Poppins', sans-serif; font-weight: 600; font-size: 14px; }
.wh-cat-count { background: #EEF0FF; color: var(--indigo-dark); font-size: 11.5px; font-weight: 700; padding: 2px 9px; border-radius: 999px; }
.wh-cat-value { margin-left: auto; font-family: 'Poppins', sans-serif; font-size: 13px; color: var(--muted); font-weight: 600; }

.wh-table { width: 100%; max-width: 100%; background: var(--white); border-radius: 20px; box-shadow: var(--shadow-sm); overflow-x: auto; overflow-y: hidden; -webkit-overflow-scrolling: touch; }
.wh-row {
  display: grid; grid-template-columns: minmax(64px, 2fr) 132px 60px 90px 100px 130px;
  align-items: center; gap: 10px; padding: 12px 16px;
  border-bottom: 1px solid var(--line); font-size: 13.5px; font-family: 'Inter', sans-serif;
  min-width: 580px;
}

/* Наименование остаётся видимым при прокрутке строки вбок — "прилипает"
   к левому краю, как закреплённая область в Excel. Нужен свой фон у ячейки,
   иначе сквозь неё будет видно то, что уезжает под неё при прокрутке. */
.wh-sticky-col {
  position: sticky; left: 0; z-index: 2;
  background: var(--white); padding-right: 10px;
  box-shadow: 6px 0 8px -6px rgba(35,42,59,0.08);
}
.wh-row-head .wh-sticky-col { background: #F8F9FC; }
.wh-sticky-col-low { background: #FDF1EF; }
.wh-row-log { grid-template-columns: 92px 150px 1.6fr 60px 90px 1.6fr 100px; min-width: 780px; }
.wh-row-log .wh-col-name:not(.wh-muted) { white-space: normal; overflow-wrap: anywhere; line-height: 1.35; }
.wh-obj-cell { display: flex; flex-direction: column; align-items: flex-start; gap: 3px; min-width: 0; }
.wh-obj-name { font-size: 11.5px; color: var(--muted); font-weight: 600; line-height: 1.3; overflow-wrap: anywhere; }
.wh-obj-old { opacity: .6; }
.wh-obj-old .wh-apt-badge { background: #ECEEF3; color: #7C8599; }
.wh-obj-old .wh-obj-num { font-style: italic; }
.wh-obj-old .wh-obj-name { font-style: italic; }
.wh-old-tag { margin-left: 4px; font-size: 9.5px; font-weight: 700; text-transform: uppercase; letter-spacing: .4px; }
.wh-row-cancelled { opacity: .55; text-decoration: line-through; }
.wh-row-cancelled .wh-apt-badge, .wh-row-cancelled .wh-cancelled-badge { text-decoration: none; }
.wh-cancelled-badge {
  display: inline-flex; align-items: center; font-size: 11px; font-weight: 700;
  color: var(--neg); background: #FDEDEA; padding: 5px 10px; border-radius: 999px;
}
.wh-row-receipt { grid-template-columns: 92px 1.8fr 110px 90px 110px 1.4fr; min-width: 620px; }
.wh-row:last-child { border-bottom: none; }
.wh-row-head { background: #F8F9FC; color: var(--muted); font-size: 11px; font-weight: 700; letter-spacing: .03em; text-transform: uppercase; padding: 12px 16px; }
.wh-row-low { background: #FDF1EF; }
.wh-col-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.wh-col-wrap { white-space: normal; word-break: break-word; line-height: 1.4; align-self: center; }

.wh-qty-cell { display: flex; align-items: center; gap: 6px; }
.wh-qty-btn {
  width: 22px; height: 22px; border-radius: 7px; border: 1px solid var(--line);
  background: #F6F8FC; cursor: pointer; font-size: 13px; line-height: 1; color: var(--text);
  display: flex; align-items: center; justify-content: center;
}
.wh-qty-btn:hover { background: #EEF0FF; border-color: var(--indigo); }

.wh-row-actions { display: flex; align-items: center; gap: 8px; justify-content: flex-end; }

.wh-icon-btn-active { background: #EEF0FF; }
.wh-link-count {
  display: inline-flex; align-items: center; justify-content: center;
  min-width: 15px; height: 15px; border-radius: 999px; margin-left: 2px;
  background: var(--indigo); color: #fff; font-size: 9.5px; font-weight: 700; padding: 0 3px;
}

.wh-purchase-links { background: #F9FAFD; border-bottom: 1px solid var(--line); padding: 14px 16px 16px; }
.wh-purchase-links-list { display: flex; flex-direction: column; gap: 4px; margin-bottom: 12px; }
.wh-purchase-link-row {
  display: grid; grid-template-columns: 1.6fr 90px 1.4fr 90px 28px;
  align-items: center; gap: 10px; padding: 7px 10px; font-size: 12.5px;
  background: var(--white); border-radius: 10px;
}
.wh-purchase-link-row a { color: var(--indigo-dark); text-decoration: underline; }
.wh-purchase-link-form { display: grid; grid-template-columns: 1fr; gap: 8px; }
.wh-purchase-link-form input {
  font: inherit; font-size: 12.5px; border: 1px solid var(--line); border-radius: 10px;
  padding: 8px 10px; background: var(--white);
}
.wh-purchase-link-form .wh-btn-primary { padding: 8px 16px; font-size: 12.5px; }
.wh-badge-low { display: inline-flex; align-items: center; gap: 4px; color: var(--neg); font-size: 11px; font-weight: 700; background: #FDEDEA; padding: 3px 8px; border-radius: 999px; }
.wh-icon-btn { background: none; border: none; color: var(--muted); cursor: pointer; padding: 5px; border-radius: 8px; display: inline-flex; }
.wh-icon-btn:hover { background: #EEF0FF; color: var(--indigo-dark); }

.wh-icon-btn-danger {
  display: inline-flex; align-items: center; justify-content: center;
  width: 34px; height: 34px; border-radius: 999px; flex-shrink: 0;
  background: #FDEDEA; border: 1px solid #F3C4B8; color: var(--neg); cursor: pointer;
  transition: background .15s ease;
}
.wh-icon-btn-danger:hover { background: #FBDFD9; }

.wh-empty { padding: 26px; text-align: center; color: var(--muted); font-size: 13.5px; }

/* ---- assets (общескладской инвентарь) ---- */
.wh-asset-list { display: flex; flex-direction: column; gap: 14px; margin-bottom: 30px; }
.wh-asset-card { background: var(--white); border-radius: 18px; box-shadow: var(--shadow-sm); padding: 18px 20px; }
.wh-asset-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 14px; flex-wrap: wrap; margin-bottom: 12px; }
.wh-asset-name { font-family: 'Poppins', sans-serif; font-weight: 700; font-size: 15px; }
.wh-asset-total { font-size: 12px; color: var(--muted); font-weight: 600; margin-top: 2px; }
.wh-asset-locations { display: flex; flex-wrap: wrap; gap: 8px; }
.wh-asset-loc-badge {
  display: inline-flex; align-items: center; gap: 5px;
  background: #E4E9FB; color: var(--indigo-dark); font-size: 12px; font-weight: 600;
  padding: 5px 11px; border-radius: 999px;
}
.wh-asset-loc-badge.warehouse { background: #EEF0FF; color: var(--text); }
.wh-asset-loc-badge strong { font-family: 'Poppins', sans-serif; }

.wh-asset-inline-form { display: flex; align-items: center; gap: 8px; margin-top: 14px; flex-wrap: wrap; }
.wh-asset-inline-form input {
  font: inherit; font-size: 13.5px; border: 1px solid var(--line); border-radius: 10px;
  padding: 8px 12px; background: #F9FAFD; width: 160px;
}
.wh-asset-transfer-form { margin-top: 16px; padding-top: 16px; border-top: 1px solid var(--line); }

.wh-row-transfer { grid-template-columns: 92px 1.3fr 1.3fr 1.3fr 70px 1.4fr; min-width: 680px; }
.wh-row-audit { grid-template-columns: 140px 170px 1.2fr 1.8fr 120px; min-width: 760px; }

/* ---- issue log ---- */
.wh-log-header { display: flex; justify-content: space-between; align-items: center; margin: 28px 0 14px; flex-wrap: wrap; gap: 10px; }
.wh-apt-badge {
  display: inline-flex; align-items: center; gap: 5px; width: fit-content;
  background: #E4E9FB; color: var(--indigo-dark); font-weight: 700; font-size: 12.5px;
  padding: 4px 10px; border-radius: 999px;
}
.wh-apt-badge-clickable { border: none; cursor: pointer; font-family: inherit; }
.wh-apt-badge-clickable:hover { background: #D7DEFA; }

/* ---- object management ---- */
.wh-objects-list { display: flex; flex-direction: column; gap: 6px; max-height: 340px; overflow-y: auto; }
.wh-object-row { display: grid; grid-template-columns: 48px 1fr auto; align-items: center; gap: 12px; padding: 8px 10px; border-radius: 10px; background: #F9FAFD; }
.wh-object-row.inactive { opacity: .55; }
.wh-object-row .wh-btn-ghost { padding: 6px 12px; font-size: 12px; }

/* ---- report ---- */
.wh-report-controls { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.wh-period-switch { display: flex; gap: 4px; background: #F6F8FC; border-radius: 999px; padding: 4px; }
.wh-period-switch button { border: none; background: transparent; font: inherit; font-size: 12.5px; font-weight: 600; padding: 8px 14px; border-radius: 999px; cursor: pointer; color: var(--muted); flex-shrink: 0; white-space: nowrap; }
.wh-period-switch button.active { background: var(--indigo); color: #fff; }
.wh-pill-dropdown { position: relative; }
.wh-pill-trigger {
  display: inline-flex; align-items: center; gap: 8px;
  font: inherit; font-size: 12.5px; font-weight: 600; color: var(--text);
  border: 1px solid var(--line); border-radius: 999px; padding: 8px 14px;
  background: var(--white); cursor: pointer; white-space: nowrap;
}
.wh-pill-trigger.active { border-color: var(--indigo); color: var(--indigo-dark); box-shadow: 0 0 0 1px var(--indigo) inset; }
.wh-pill-backdrop { position: fixed; inset: 0; z-index: 20; }
.wh-pill-menu {
  position: absolute; top: calc(100% + 6px); right: 0; z-index: 21;
  background: var(--white); border-radius: 14px; box-shadow: var(--shadow-lg);
  padding: 6px; min-width: 190px; max-height: 320px; overflow-y: auto;
  display: flex; flex-direction: column; gap: 1px;
}
.wh-pill-menu-item {
  display: flex; align-items: center; gap: 8px; text-align: left;
  border: none; background: transparent; font: inherit; font-size: 13px; font-weight: 500;
  color: var(--text); padding: 9px 10px; border-radius: 9px; cursor: pointer; white-space: nowrap;
}
.wh-pill-menu-item:hover { background: #F0F2FA; }
.wh-pill-menu-item.selected { background: var(--indigo); color: #fff; font-weight: 600; }
.wh-pill-menu-item.trailing { margin-top: 5px; border-top: 1px solid var(--line); padding-top: 11px; border-radius: 0 0 9px 9px; }
.wh-pill-menu-check { width: 14px; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }

/* ---- material combo (поисковый список материалов в выдаче) ---- */
.wh-material-combo { position: relative; }
.wh-material-trigger {
  width: 100%; display: flex; align-items: center; justify-content: space-between; gap: 10px;
  font: inherit; font-size: 13.5px; text-align: left; color: var(--text);
  border: 1px solid var(--line); border-radius: 12px; padding: 11px 14px;
  background: #F9FAFD; cursor: pointer;
}
.wh-material-trigger:hover { border-color: var(--indigo); }
.wh-material-menu {
  position: absolute; top: calc(100% + 6px); left: 0; right: 0; z-index: 21;
  background: var(--white); border-radius: 16px; box-shadow: var(--shadow-lg);
  padding: 10px; max-height: 380px; display: flex; flex-direction: column;
}
.wh-material-menu-header { display: flex; align-items: center; gap: 8px; margin-bottom: 8px; flex-shrink: 0; }
.wh-material-close {
  display: flex; align-items: center; gap: 4px; flex-shrink: 0;
  border: none; background: #F0F2FA; color: var(--text); font: inherit; font-size: 12.5px; font-weight: 600;
  padding: 9px 12px; border-radius: 10px; cursor: pointer;
}
.wh-material-close:hover { background: #E4E9FB; }
.wh-material-search {
  display: flex; align-items: center; gap: 8px; color: var(--muted); flex: 1 1 auto; min-width: 0;
  border: 1px solid var(--line); border-radius: 10px; padding: 9px 12px; margin-bottom: 0;
}
.wh-material-search input { border: none; outline: none; font: inherit; font-size: 13.5px; width: 100%; background: transparent; color: var(--text); }
.wh-material-list { overflow-y: auto; overflow-x: hidden; flex: 1 1 auto; min-height: 0; max-width: 100%; }
.wh-material-group-label {
  font-size: 10.5px; font-weight: 700; color: var(--muted); text-transform: uppercase; letter-spacing: .02em;
  padding: 8px 8px 4px;
}
.wh-material-option {
  width: 100%; max-width: 100%; display: flex; align-items: center; justify-content: space-between; gap: 10px;
  border: none; background: transparent; text-align: left; font: inherit; font-size: 13px;
  padding: 8px 8px; border-radius: 9px; cursor: pointer; color: var(--text);
}
/* Длинное название товара не должно расталкивать строку (а с ней и всю
   страницу) по ширине — у flex-элемента по умолчанию min-width:auto, из-за
   чего он не сжимался, и страница на телефоне "расползалась" и переставала
   нормально масштабироваться. min-width:0 разрешает ему сжиматься и уйти
   в многоточие вместо этого. */
.wh-material-option .wh-col-name { min-width: 0; flex: 1 1 auto; }
.wh-material-option .wh-mono { flex-shrink: 0; }
.wh-material-option:hover { background: #F0F2FA; }
.wh-material-option.selected { background: var(--indigo); color: #fff; }
.wh-material-option.selected .wh-mono { color: rgba(255,255,255,0.8); }
.wh-material-option:disabled { opacity: .45; cursor: not-allowed; }

.wh-stat-cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; margin-bottom: 26px; }
.wh-stat-cards-5 { grid-template-columns: repeat(5, 1fr); }
.wh-stat-card { background: var(--white); border-radius: 18px; box-shadow: var(--shadow-sm); padding: 18px 20px; display: flex; flex-direction: column; gap: 8px; color: var(--indigo-dark); }
.wh-stat-card-accent { background: #FFF7E8; box-shadow: var(--shadow-sm), 0 0 0 1px var(--orange-2) inset; }
.wh-stat-card-value { font-family: 'Poppins', sans-serif; font-size: 21px; font-weight: 700; color: var(--text); }
.wh-stat-card-label { font-size: 12px; color: var(--muted); font-weight: 600; }

.wh-markup-row { display: flex; justify-content: space-between; align-items: center; gap: 16px; flex-wrap: wrap; background: var(--white); border-radius: 16px; box-shadow: var(--shadow-sm); padding: 14px 18px; margin-bottom: 18px; }
.wh-markup-label { font-size: 13px; color: var(--text); }
.wh-markup-label strong { font-family: 'Poppins', sans-serif; color: var(--indigo-dark); }
.wh-markup-edit { display: flex; align-items: center; gap: 6px; }
.wh-markup-edit input { width: 64px; font: inherit; font-size: 13.5px; border: 1px solid var(--line); border-radius: 10px; padding: 8px 10px; background: #F9FAFD; text-align: right; }
.wh-markup-edit span { font-size: 13px; color: var(--muted); font-weight: 600; }

.wh-report-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; align-items: start; }
.wh-report-block { background: var(--white); border-radius: 20px; box-shadow: var(--shadow-sm); padding: 20px 22px; }

.wh-bar-row { display: grid; grid-template-columns: 74px 1fr 92px 64px; align-items: center; gap: 10px; padding: 8px 0; }
.wh-report-block:last-child .wh-bar-row { grid-template-columns: 118px 1fr 92px; }
.wh-bar-track { height: 8px; background: var(--line); border-radius: 20px; overflow: hidden; }
.wh-bar-track-wrap { display: flex; flex-direction: column; gap: 4px; }
.wh-room-name-reveal { font-size: 11.5px; color: var(--muted); font-weight: 600; }

.wh-room-block { border-bottom: 1px solid var(--line); }
.wh-room-block:last-child { border-bottom: none; }
.wh-room-block .wh-bar-row { border-bottom: none; }
.wh-room-detail { padding: 4px 0 12px 84px; display: flex; flex-direction: column; gap: 2px; }
.wh-room-detail-row { display: grid; grid-template-columns: 70px 1.6fr 56px 76px 76px 76px; gap: 8px; align-items: center; padding: 5px 0; font-size: 12px; }
.wh-room-detail-head { color: var(--muted); font-size: 10.5px; font-weight: 700; text-transform: uppercase; letter-spacing: .02em; padding-bottom: 6px; }
.wh-bar-fill { height: 100%; border-radius: 20px; background: linear-gradient(90deg, var(--orange-1), var(--orange-2)); }
.wh-bar-fill-alt { background: linear-gradient(90deg, var(--blue-1), var(--indigo-dark)); }
.wh-bar-value { text-align: right; font-family: 'Poppins', sans-serif; }
.wh-bar-count { text-align: right; font-size: 11.5px; color: var(--muted); }
.wh-cat-tag { font-size: 12.5px; font-weight: 600; color: var(--text); }

@media (max-width: 900px) {
  .wh-wallet-row { grid-template-columns: repeat(2, 1fr); }
  .wh-report-grid { grid-template-columns: 1fr; }
  .wh-stat-cards { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 560px) {
  .wh-wallet-row { grid-template-columns: repeat(2, 1fr); gap: 10px; }
  .wh-wallet-card { padding: 14px 14px 16px; border-radius: 16px; }
  .wh-wallet-icon { width: 28px; height: 28px; font-size: 14px; border-radius: 9px; margin-bottom: 10px; }
  .wh-wallet-card .w-label { font-size: 11px; margin-bottom: 6px; }
  .wh-wallet-card .w-value { font-size: 15px; margin-bottom: 2px; }
  .wh-wallet-card .w-sub { font-size: 9.5px; }
  .wh-stat-cards { grid-template-columns: 1fr; }
  .wh-hero-top-row { gap: 10px; }
  .wh-tab-pill-wrap { width: 100%; flex: 1 1 100%; }
  .wh-role-badge {
    padding: 5px 6px 5px 10px; gap: 6px;
  }
  .wh-role-badge span { font-size: 11px; }
  .wh-logout-btn { padding: 5px 9px; font-size: 10.5px; }
  .wh-purchase-link-row { grid-template-columns: 1fr; row-gap: 4px; }
  .wh-cost-calc-row { flex-direction: column; align-items: flex-start; gap: 2px; }
  .wh-panel { padding: 16px 16px; }
  .wh-hint-banner { font-size: 11.5px; padding: 10px 12px; margin-bottom: 12px; }
  .wh-cost-calc { padding: 10px 12px; }
  .wh-price-history { padding: 10px 12px; }
  .wh-price-history-row { grid-template-columns: 1fr; row-gap: 2px; }
  .wh-form-grid label { gap: 3px; }
  .wh-form-grid input, .wh-form-grid select { padding: 8px 10px; }
  .wh-panel-actions {
    position: sticky; bottom: 0; margin: 16px -16px -16px;
    padding: 12px 16px; background: var(--white);
    border-top: 1px solid var(--line); border-radius: 0 0 22px 22px;
  }

  /* На телефоне это меню — полноэкранное окно, а не плавающая панель под
     полем: так открытая клавиатура не перекрывает список, а кнопка
     "Закрыть" в шапке всегда на виду и не зависит от клика по фону, который
     на мобильном мог срабатывать ненадёжно (особенно с открытой клавиатурой). */
  .wh-material-menu {
    position: fixed; inset: 0; z-index: 60;
    border-radius: 0; max-height: none;
    padding: calc(env(safe-area-inset-top, 0px) + 18px) 14px 14px;
  }
  .wh-material-menu-header { margin-bottom: 12px; }
  .wh-material-close { padding: 11px 14px; }

  /* 16px в полях ввода — иначе iPhone при нажатии увеличивает страницу и
     потом не возвращает масштаб. */
  .wh-root input, .wh-root select, .wh-root textarea { font-size: 16px !important; }

  /* Детализация расходов по объекту: вместо узкой таблицы — аккуратные
     карточки, чтобы ничего не обрезалось справа. */
  .wh-room-detail { padding: 4px 0 10px 0; gap: 0; }
  .wh-room-detail-head { display: none; }
  .wh-room-detail-row {
    grid-template-columns: repeat(4, 1fr); column-gap: 8px; row-gap: 6px;
    padding: 10px 0; border-bottom: 1px solid var(--line); font-size: 12.5px;
  }
  .wh-room-detail-row:last-child { border-bottom: none; }
  .wh-room-detail-row > span:nth-child(1) { grid-column: 1 / 2; }
  .wh-room-detail-row > span:nth-child(2) {
    grid-column: 2 / 5; white-space: normal; overflow: visible; text-overflow: clip;
    font-weight: 600; font-size: 13px; overflow-wrap: anywhere;
  }
  .wh-room-detail-row > span[data-label]::before {
    content: attr(data-label); display: block; font-family: 'Inter', sans-serif;
    font-size: 9.5px; font-weight: 700; text-transform: uppercase; letter-spacing: .02em;
    color: var(--muted); margin-bottom: 1px;
  }
}
`;
